const fs = require('fs');
const rows = $input.all().map(i => i.json).filter(r => r && r.slug);

let hasGscFile = false;
try {
  if (fs.existsSync('/credentials/gsc-service-account.json')) {
    const sa = JSON.parse(fs.readFileSync('/credentials/gsc-service-account.json', 'utf8'));
    if (sa.client_email && sa.private_key) hasGscFile = true;
  }
} catch (e) {}

if (!rows.length) {
  return [{ json: { result: '[MANAGED_SITES]\nBelum ada website yang terdaftar di database seo_sites.\n[/MANAGED_SITES]' } }];
}

const lines = [
  '[MANAGED_SITES]',
  `Total website terdaftar: ${rows.length}`,
  `Status Google Service Account: ${hasGscFile ? '✅ Terpasang di credentials/gsc-service-account.json' : '⚠️ Belum ada file credentials/gsc-service-account.json'}`,
  ''
];

rows.forEach((s, idx) => {
  lines.push(`--- Website #${idx + 1} ---`);
  lines.push(`Nama: ${s.name}`);
  lines.push(`Slug (ID): ${s.slug}`);
  lines.push(`Domain: ${s.domain}`);
  lines.push(`WordPress URL: ${s.wp_base_url}`);
  lines.push(`GSC Property: ${s.gsc_property || '(belum disetel)'}`);
  lines.push(`Konten terindeks di DB: ${s.indexed_pages || 0} halaman${s.last_indexed ? ` (terakhir: ${s.last_indexed})` : ' (belum pernah di-ingest)'}`);
  lines.push('');
});

lines.push('Catatan: Untuk menganalisis website tertentu, sebutkan nama website atau domainnya di chat.');
lines.push('[/MANAGED_SITES]');

return [{ json: { result: lines.join('\n') } }];
